-- station_master に line（路線名）列を追加し、ekidata.jp実データで全面再シードする。
-- 目的: 同名駅（例: 府中＝広島/徳島/東京）を路線で判別できるようにする。
-- 出典: ekidata.jp（駅データ.jp）2026-07時点ダウンロード。ユーザーが会員登録の上取得した
--       station/line CSVをスクリプトで変換（AI生成ではなく実データの機械的変換）。
-- 参考: docs/station_prefecture_extraction_design.md

-- 既存の「駅名だけでユニーク」制約を撤廃（同名駅を複数路線で複数行持つため）
DROP INDEX IF EXISTS idx_station_master_name;

-- line列を追加（既存データはNULLのまま残る。この直後に全面差し替えする）
ALTER TABLE station_master ADD COLUMN IF NOT EXISTS line text;

-- 同一(駅名,路線名,都道府県)の重複だけ防ぐ
CREATE UNIQUE INDEX IF NOT EXISTS idx_station_master_name_line_pref
  ON station_master(name, line, prefecture);

-- 駅名だけでの検索も高速化（線なし照合のフォールバック用）
CREATE INDEX IF NOT EXISTS idx_station_master_name ON station_master(name);

-- 全面差し替え（旧データ8,685件を削除し、ekidata由来の実データに置き換える）
TRUNCATE station_master;
